import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object
  const root = new Group();

  // Geometry for the thin rule
  const geometry = new PlaneGeometry(2, 0.2, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.metalness = 0.3;
  material.roughness = 0.6;
  material.clearcoat = 0.1;
  material.transparent = true;

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Store disposables
  const disposables = [];
  const timelines = [];
  const primitiveInstances = [];

  // Load textures
  const colorTexPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthTexPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  colorTexPromise.then((tex) => {
    disposables.push(tex);
    material.colorNode = texture(tex).rgb;
    material.needsUpdate = true;
  });

  depthTexPromise.then((tex) => {
    disposables.push(tex);
    const dispScale = uniform(0.1);
    material.displacementNode = texture(tex).r.mul(dispScale);
    material.displacementScale = 0.1;
    material.needsUpdate = true;
  });

  // Parallax primitive (required for render mode)
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const parallax = ctx.primitives['parallax-scroll'](root, {});
    primitiveInstances.push(parallax);
  }

  // Interaction handlers
  const hoverTimeline = gsap.timeline({ paused: true });
  timelines.push(hoverTimeline);

  const handlers = {
    hover: () => {
      hoverTimeline.clear();
      hoverTimeline.to(root.position, {
        y: root.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    click: () => {
      ctx.emit('hub-features.select', {});
    },
  };
  root.userData.handlers = handlers;

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures
    disposables.forEach((tex) => tex.dispose && tex.dispose());

    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());

    // Cleanup primitives
    primitiveInstances.forEach((inst) => inst.cleanup && inst.cleanup());
  };

  return root;
}
